namespace volumetric_kit::grid::codec::detail {
namespace {

// Mirrors `Push` in block_lists_push.glsl.
struct ListsPush {
  std::uint32_t item_base = 0;
  std::uint32_t count = 0;
  std::uint32_t count_word = 0;
  std::uint32_t run_length = 0;
  std::uint32_t reference_count = 0;
  std::uint32_t new_count = 0;
  std::uint32_t block_count = 0;
  std::uint32_t pass = 0;
  std::int32_t num_buckets = 0;
  std::int32_t bucket_size = 0;
  std::int32_t max_chain = 0;
};
static_assert(sizeof(ListsPush) == 44, "ListsPush must be 44 bytes");

// The entries block_sort_tile.comp sorts a workgroup (kSortTile there), and
// the other kernels' width.
constexpr std::uint32_t kSortTile = 256;
constexpr std::uint32_t kLanes = 256;

constexpr VkDeviceSize kEntryBytes = sizeof(volume::BlockIndex);
constexpr VkDeviceSize kWordBytes = sizeof(std::uint32_t);
// The merge's collision pair, and the diff's two counts.
constexpr VkDeviceSize kPairBytes = 2 * kWordBytes;

core::Status fail(const char* op, const std::string& why) {
  return core::Status::invalid_argument(std::string("BlockLists::") + op +
                                        ": " + why);
}

}  // namespace

core::Result<std::unique_ptr<BlockLists>> BlockLists::create(
    core::Device& device, core::Allocator& allocator) {
  VKC_TRY(check_device_requirements(device, "BlockLists::create"));
  std::unique_ptr<BlockLists> owned(new BlockLists());
  BlockLists& l = *owned;
  l.device_ = &device;
  l.allocator_ = &allocator;
  VkPushConstantRange push{};
  push.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
  push.size = sizeof(ListsPush);
  core::KernelSetBuilder kb(device);
  VKC_TRY(kb.add(l.sort_tile_kernel_, "codec_block_sort_tile",
                 vgrid_block_sort_tile_comp_spv,
                 vgrid_block_sort_tile_comp_spv_size, 3, &push));
  VKC_TRY(kb.add(l.sort_merge_kernel_, "codec_block_sort_merge",
                 vgrid_block_sort_merge_comp_spv,
                 vgrid_block_sort_merge_comp_spv_size, 3, &push));
  VKC_TRY(kb.add(l.frame_merge_kernel_, "codec_frame_merge",
                 vgrid_frame_merge_comp_spv, vgrid_frame_merge_comp_spv_size, 7,
                 &push));
  VKC_TRY(kb.add(l.grid_diff_kernel_, "codec_grid_diff",
                 vgrid_grid_diff_comp_spv, vgrid_grid_diff_comp_spv_size, 5,
                 &push));
  VKC_ASSIGN(l.pool_, kb.build());
  VKC_TRY(l.sort_merge_sets_.reserve(device, l.sort_merge_kernel_, 3));
  VkPhysicalDeviceProperties props{};
  vkGetPhysicalDeviceProperties(device.physical_device(), &props);
  l.max_workgroup_count_x_ = props.limits.maxComputeWorkGroupCount[0];
  l.max_storage_buffer_range_ = props.limits.maxStorageBufferRange;
  // The words that come back, and an entry of each list, so a frame of no
  // blocks, or a grid of none, binds a buffer.
  struct First {
    core::Buffer& buffer;
    VkDeviceSize bytes;
    const char* name;
  };
  const First first[] = {
      {l.collision_, kPairBytes, "codec.merge_collision"},
      {l.diff_counts_, kPairBytes, "codec.diff_counts"},
      {l.gone_, kEntryBytes, "codec.diff_gone"},
      {l.missing_, kEntryBytes, "codec.diff_missing"},
  };
  for (const First& f : first) {
    VKC_TRY(core::ensure_device_scratch(device, allocator, f.buffer, f.bytes,
                                        l.max_storage_buffer_range_, f.name));
  }
  return owned;
}

core::Status BlockLists::record_sort(core::CommandBatch& batch,
                                     const core::Buffer& list,
                                     const volume::DeviceCount& count,
                                     const core::Buffer& out,
                                     core::GpuStageScope* stage) {
  const std::uint32_t bound = count.bound;
  if (bound == 0) return {};
  const VkDeviceSize bytes = VkDeviceSize(bound) * kEntryBytes;
  const VkDeviceSize range = max_storage_buffer_range_;
  VKC_TRY(core::StorageInput(list).check("BlockLists::record_sort: the list",
                                         bytes));
  VKC_TRY(core::check_storage_buffer_range("BlockLists::record_sort: the list",
                                           bytes, range));
  if (count.buffer == nullptr || !count.buffer->valid() ||
      count.offset % kWordBytes != 0 ||
      count.buffer->size() < count.offset + kWordBytes || out.size() < bytes) {
    return fail("record_sort",
                "the count's word is missing, misaligned or past its buffer, "
                "or the output holds fewer than the bound's entries");
  }
  // The levels the bound needs: each doubles the sorted runs, from the
  // tiles' to the whole list. The count may need fewer, and a level past
  // them copies its entries through; the last level, or the tile pass with
  // none, writes the output.
  std::uint32_t levels = 0;
  for (std::uint64_t run = kSortTile; run < bound; run *= 2) ++levels;
  for (std::uint32_t h = 0; h < std::min<std::uint32_t>(levels, 2); ++h) {
    VKC_TRY(core::ensure_device_scratch(*device_, *allocator_, sorted_[h],
                                        bytes, range, "codec.sorted_blocks",
                                        &batch));
  }
  const core::Buffer& tiles = levels == 0 ? out : sorted_[0];
  sort_tile_kernel_.set.write_storage_buffer(0, list.handle(), 0, bytes);
  sort_tile_kernel_.set.write_storage_buffer(1, tiles.handle(), 0, bytes);
  sort_tile_kernel_.set.write_storage_buffer(2, count.buffer->handle(), 0,
                                             VK_WHOLE_SIZE);
  // Level l merges sorted_[l % 2] into the other half, through set l % 2,
  // but the last, which merges into the output through set 2.
  const auto bind = [&](std::uint32_t set, const core::Buffer& src,
                        const core::Buffer& dst) {
    sort_merge_sets_[set].write_storage_buffer(0, src.handle(), 0, bytes);
    sort_merge_sets_[set].write_storage_buffer(1, dst.handle(), 0, bytes);
    sort_merge_sets_[set].write_storage_buffer(2, count.buffer->handle(), 0,
                                               VK_WHOLE_SIZE);
  };
  if (levels >= 2) bind(0, sorted_[0], sorted_[1]);
  if (levels >= 3) bind(1, sorted_[1], sorted_[0]);
  if (levels >= 1) bind(2, sorted_[(levels - 1) % 2], out);
  // Every pass over the bound's groups: a group past the count returns.
  ListsPush push;
  push.count = bound;
  push.count_word = static_cast<std::uint32_t>(count.offset / kWordBytes);
  VKC_TRY(dispatch_items(batch, sort_tile_kernel_, push, bound, kSortTile,
                         max_workgroup_count_x_, stage));
  std::uint32_t level = 0;
  for (std::uint64_t run = kSortTile; run < bound; run *= 2, ++level) {
    push.run_length = static_cast<std::uint32_t>(run);
    const core::DescriptorSet& set =
        sort_merge_sets_[level + 1 == levels ? 2u : level % 2];
    VKC_TRY(dispatch_items(batch, sort_merge_kernel_, push, bound, kLanes,
                           max_workgroup_count_x_, stage, &set));
  }
  return {};
}

core::Status BlockLists::reserve(std::uint32_t n, std::uint32_t slots) {
  struct Scratch {
    core::Buffer& buffer;
    VkDeviceSize bytes;
    const char* name;
  };
  const Scratch scratch[] = {
      {gone_, VkDeviceSize(slots) * kEntryBytes, "codec.diff_gone"},
      {missing_, VkDeviceSize(n) * kEntryBytes, "codec.diff_missing"},
  };
  // Every range first, so a frame the device cannot hold grows nothing.
  for (const Scratch& b : scratch) {
    VKC_TRY(core::check_storage_buffer_range(b.name, b.bytes,
                                             max_storage_buffer_range_));
  }
  for (const Scratch& b : scratch) {
    VKC_TRY(core::ensure_device_scratch(*device_, *allocator_, b.buffer,
                                        b.bytes, max_storage_buffer_range_,
                                        b.name));
  }
  return {};
}

core::Status BlockLists::record_merge(core::CommandBatch& batch,
                                      const ResidentBlocks& decoded,
                                      const core::Buffer& reference,
                                      FrameBuffers frame, std::uint32_t n,
                                      core::GpuStageScope* stage) {
  const std::uint32_t m = decoded.reference_count;
  const std::uint32_t a = decoded.count - m;
  const VkDeviceSize ref_bytes = binding_range(m * kEntryBytes, kEntryBytes);
  const VkDeviceSize added_bytes = binding_range(a * kEntryBytes, kEntryBytes);
  const VkDeviceSize mode_bytes = binding_range(m * kWordBytes, kWordBytes);
  const VkDeviceSize rank_bytes = (VkDeviceSize(m) + 1) * kWordBytes;
  const VkDeviceSize frame_bytes = binding_range(n * kEntryBytes, kEntryBytes);
  const VkDeviceSize source_bytes =
      binding_range(VkDeviceSize(n) * sizeof(ApplySource), sizeof(ApplySource));
  const bool entries = decoded.count != 0;
  if (entries &&
      (decoded.list == nullptr || (m != 0 && decoded.modes == nullptr) ||
       decoded.ranks == nullptr || frame.list == nullptr ||
       frame.sources == nullptr || decoded.list->size() < added_bytes ||
       (m != 0 && decoded.modes->size() < mode_bytes) ||
       decoded.ranks->size() < rank_bytes || reference.size() < ref_bytes ||
       frame.list->size() < frame_bytes ||
       frame.sources->size() < source_bytes)) {
    return fail("record_merge", "the buffers do not hold " + std::to_string(m) +
                                    " reference entries, " + std::to_string(a) +
                                    " new blocks and " + std::to_string(n) +
                                    " frame blocks");
  }
  VKC_TRY(batch.fill(collision_, 0, kPairBytes, kNoSource));
  if (entries) {
    const core::DescriptorSet& set = frame_merge_kernel_.set;
    set.write_storage_buffer(0, reference.handle(), 0, ref_bytes);
    set.write_storage_buffer(1, decoded.list->handle(), 0, added_bytes);
    // An intra frame's modes are never read; its ranks stand in.
    set.write_storage_buffer(
        2, m != 0 ? decoded.modes->handle() : decoded.ranks->handle(), 0,
        mode_bytes);
    set.write_storage_buffer(3, decoded.ranks->handle(), 0, rank_bytes);
    set.write_storage_buffer(4, frame.list->handle(), 0, frame_bytes);
    set.write_storage_buffer(5, frame.sources->handle(), 0, source_bytes);
    set.write_storage_buffer(6, collision_.handle(), 0, kPairBytes);
    ListsPush push;
    push.count = decoded.count;
    push.reference_count = m;
    push.new_count = a;
    push.block_count = n;
    VKC_TRY(dispatch_items(batch, frame_merge_kernel_, push, decoded.count,
                           kLanes, max_workgroup_count_x_, stage));
  }
  return {};
}

core::Status BlockLists::record_diff(core::CommandBatch& batch,
                                     const volume::VoxelBlockGrid& grid,
                                     const core::Buffer& frame_list,
                                     std::uint32_t n,
                                     core::GpuStageScope* stage) {
  if (!grid.valid()) return fail("record_diff", "moved-from grid");
  const volume::VoxelGridParams& gp = grid.grid();
  const auto slots =
      static_cast<std::uint32_t>(gp.num_buckets * gp.bucket_size);
  // Another tier sized the table (and every resize doubles it), so it is
  // bound at its real size and range-checked, and fetched for this call: a
  // resize replaces it.
  const VkDeviceSize entries_bytes =
      volume::VoxelHashMap::Internal::entries_buffer_size(grid.map());
  VKC_TRY(core::check_storage_buffer_range("BlockLists: the hash entries",
                                           entries_bytes,
                                           max_storage_buffer_range_));
  const VkDeviceSize frame_bytes = binding_range(n * kEntryBytes, kEntryBytes);
  const VkDeviceSize gone_bytes =
      binding_range(VkDeviceSize(slots) * kEntryBytes, kEntryBytes);
  if (gone_.size() < gone_bytes || missing_.size() < frame_bytes ||
      frame_list.size() < frame_bytes) {
    return fail("record_diff", std::to_string(n) + " frame blocks and " +
                                   std::to_string(slots) +
                                   " slots, more than were reserved");
  }
  const core::DescriptorSet& set = grid_diff_kernel_.set;
  set.write_storage_buffer(
      0, volume::VoxelHashMap::Internal::entries_buffer(grid.map()), 0,
      entries_bytes);
  set.write_storage_buffer(1, frame_list.handle(), 0, frame_bytes);
  set.write_storage_buffer(2, gone_.handle(), 0, gone_bytes);
  set.write_storage_buffer(3, missing_.handle(), 0, frame_bytes);
  set.write_storage_buffer(4, diff_counts_.handle(), 0, kPairBytes);
  VKC_TRY(batch.fill(diff_counts_, 0, kPairBytes, 0u));
  ListsPush push;
  push.block_count = n;
  push.num_buckets = gp.num_buckets;
  push.bucket_size = gp.bucket_size;
  push.max_chain = gp.max_chain;
  // The table's slots against the frame, then the frame against the table.
  for (const std::uint32_t pass : {0u, 1u}) {
    push.pass = pass;
    push.count = pass == 0 ? slots : n;
    VKC_TRY(dispatch_items(batch, grid_diff_kernel_, push, push.count, kLanes,
                           max_workgroup_count_x_, stage));
  }
  return {};
}

}  // namespace volumetric_kit::grid::codec::detail
